package com.gomgomapps.math.core;
import java.util.*;import java.util.regex.*;import org.junit.Test;import static org.junit.Assert.*;
public class AnnualChangeRelationsTest {
 @Test public void publicAmountsDriveEveryYearIndependently(){Generator g=new Generator(new Random(1840));Set<String> variants=new HashSet<>();for(String id:List.of("annualCompound","annualValueChange"))for(int i=0;i<600;i++){Question q=g.next(id,List.of(),i%2==0);List<Rational> v=new ArrayList<>();Matcher m=Pattern.compile("\\d+(?:\\.\\d+)?").matcher(q.prompt);while(m.find())v.add(Expression.number(m.group()));Rational balance=v.get(0),fraction=v.get(1).div(Rational.of(100));int years=(int)v.get(2).intValue();boolean fall=q.prompt.contains("하락");variants.add((id.equals("annualCompound")?"compound":fall?"fall":"rise")+years);List<Rational> expected=new ArrayList<>(v);expected.add(fraction);for(int y=1;y<=years;y++){Rational change=balance.mul(fraction);balance=fall?balance.sub(change):balance.add(change);expected.add(change);expected.add(balance);}assertTrue(new Checker().check(q,List.of(),List.of(balance.toString())).correct());verify(q,expected);}assertEquals(9,variants.size());}
 @Test public void savedDecimalsRetainExactAnnualChange(){Question q=new Question("annualValueChange","처음 금액: 125.5\n매년 2.5% 하락 · 기간: 2년\n마지막 금액은?","","119.3034375");verify(q,List.of(Rational.of(251,2),Rational.of(5,2),Rational.of(2),Rational.of(1,40),Rational.of(251,80),Rational.of(9789,80),Rational.of(9789,3200),Rational.of(381771,3200)));}
 @Test public void annualBalanceDraftCannotBecomeInitialAmount(){Question q=new Question("annualCompound","원금: 10000\n연이율: 10% · 기간: 2년\n매년 이자를 잔액에 더합니다.\n마지막 총금액은?","","12100");HelpPlan p=HelpPlan.forQuestion(q);HelpPlan.Draft d=new HelpPlan.Draft();d.questionId=q.id;d.stage=1;d.entries=new ArrayList<>(List.of("1000",""));p.restore(d,q.id);assertEquals(0,d.stage);assertEquals("",d.entries.get(0));d.entries.set(0,"10000");d.stage=1;HelpPlan.Draft restored=HelpPlan.forQuestion(q).restore(d.copy(),q.id);assertEquals(1,restored.stage);assertEquals("10000",restored.entries.get(0));}
 private void verify(Question q,List<Rational> expected){String signature=q.signature();Arrays.fill(q.answers,"999999");q.choiceInputs=new Rational[]{Rational.of(999999)};HelpPlan p=HelpPlan.forQuestion(q);assertEquals(signature,q.signature());assertEquals(expected.size(),p.size());assertFalse(p.canTransfer());for(int k=0;k<p.size();k++){assertTrue(p.step(k).accepts(expected.get(k).toString()));assertFalse(p.step(k).accepts(expected.get(k).add(Rational.ONE).toString()));assertFalse(p.step(k).before.replaceAll("[1-3]년(?:째| 뒤)","").replace("100","").matches("(?s).*\\d.*"));}}
}
